/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { OmegaPower, Ordinal, convertOrdinal, isUnsolved, pprintUseUnicode } from '../../src';
import { pyStr, sympyStr } from '../sympy-str';

describe("doctests of sympy.sets.ordinals", () => {
  it("w.is_limit_ordinal", () => {
    expect(sympyStr(Ordinal(OmegaPower(Ordinal(OmegaPower(Ordinal(), 1n)), 1n)).isLimitOrdinal)).toBe('True');
  });
  it("Ordinal(OmegaPower(w + 1, 1), OmegaPower(3, 2))", () => {
    expect(sympyStr(Ordinal(OmegaPower(Ordinal(OmegaPower(Ordinal(OmegaPower(Ordinal(), 1n)), 1n), OmegaPower(Ordinal(), 1n)), 1n), OmegaPower(Ordinal(OmegaPower(Ordinal(), 3n)), 2n)))).toBe('w**(w + 1) + w**3*2');
  });
  it("3 + w", () => {
    expect(sympyStr(convertOrdinal(3n).add(Ordinal(OmegaPower(Ordinal(OmegaPower(Ordinal(), 1n)), 1n))))).toBe('w');
  });
  it("(w + 1) * w", () => {
    expect(sympyStr(Ordinal(OmegaPower(Ordinal(OmegaPower(Ordinal(), 1n)), 1n), OmegaPower(Ordinal(), 1n)).mul(Ordinal(OmegaPower(Ordinal(OmegaPower(Ordinal(), 1n)), 1n))))).toBe('w**2');
  });
  it("omega + omega", () => {
    expect(sympyStr(Ordinal(OmegaPower(Ordinal(OmegaPower(Ordinal(), 1n)), 1n)).add(Ordinal(OmegaPower(Ordinal(OmegaPower(Ordinal(), 1n)), 1n))))).toBe('w*2');
  });
});

